-- SAM Inventory: complete database setup (generated by scripts/build-setup-sql.sh).
-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run. Run it once, on an empty project.

-- ===================== 0001_schema.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0001: schema, stock view, integrity triggers
--
-- Departures from the master prompt are tagged "SPEC FIX" with the reason.
-- =====================================================================

create schema if not exists extensions;
create extension if not exists pg_trgm with schema extensions;

-- ---------------------------------------------------------------------
-- Reference data: the three stock locations
-- ---------------------------------------------------------------------
create table public.locations (
  id         text primary key check (id in ('display', 'storage', 'warehouse')),
  name_en    text not null,
  name_ar    text not null,
  sort_order integer not null
);

insert into public.locations (id, name_en, name_ar, sort_order) values
  ('display',   'Display',   'المعرض',   1),
  ('storage',   'Storage',   'المخزن',   2),
  ('warehouse', 'Warehouse', 'المستودع', 3);

-- ---------------------------------------------------------------------
-- Staff roles
-- ---------------------------------------------------------------------
create table public.staff_roles (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  role       text not null check (role in ('admin', 'sales', 'warehouse')),
  full_name  text,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

-- Role of the calling user (NULL = not staff / deactivated). Used by RLS,
-- the stock views and every RPC.
create or replace function public.app_role()
returns text
language sql stable security definer
set search_path = public
as $$
  select role from public.staff_roles where user_id = auth.uid() and active
$$;

create or replace function public.require_role(variadic p_roles text[])
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_role text := public.app_role();
begin
  if v_role is null or not (v_role = any (p_roles)) then
    raise exception 'forbidden: requires role %', array_to_string(p_roles, ' or ')
      using errcode = '42501';
  end if;
  return v_role;
end;
$$;

-- Never leave the system without an admin.
create or replace function public.guard_last_admin()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.role = 'admin' and old.active
     and (tg_op = 'DELETE' or not (new.role = 'admin' and new.active)) then
    if not exists (
      select 1 from public.staff_roles
      where role = 'admin' and active and user_id <> old.user_id
    ) then
      raise exception 'last_admin: cannot remove, demote or deactivate the last active admin';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

create trigger staff_roles_guard_last_admin
  before update or delete on public.staff_roles
  for each row execute function public.guard_last_admin();

-- ---------------------------------------------------------------------
-- Catalog
-- SPEC FIX: kit_parent_id removed. A single FK cannot express a BOM ratio
-- ("1 kit = 2 of component X"), so kits use the kit_components table below.
-- Added: specs (present in the PDF import), cost_usd (needed for the stock
-- valuation report), reorder_level (low-stock threshold, default 3).
-- ---------------------------------------------------------------------
create table public.products (
  id                 uuid primary key default gen_random_uuid(),
  item_code          text not null,
  name               text not null,
  name_ar            text,
  category           text,
  unit               text not null default 'قطعة',
  specs              text,
  price_usd          numeric(12, 2) not null default 0 check (price_usd >= 0),
  price_syp          numeric(14, 0) not null default 0 check (price_syp >= 0),
  wireless_price_usd numeric(12, 2) check (wireless_price_usd >= 0),
  wireless_price_syp numeric(14, 0) check (wireless_price_syp >= 0),
  cost_usd           numeric(12, 2) check (cost_usd >= 0),
  for_sale           boolean not null default false,
  barcode            text,
  reorder_level      integer not null default 3 check (reorder_level >= 0),
  active             boolean not null default true,
  created_at         timestamptz not null default now(),
  constraint products_item_code_key unique (item_code),
  constraint products_item_code_nonblank check (btrim(item_code) <> ''),
  constraint products_name_nonblank check (btrim(name) <> '')
);

create unique index products_barcode_key on public.products (barcode) where barcode is not null;
create index products_for_sale_idx on public.products (for_sale) where active;
create index products_category_idx on public.products (category);
create index products_name_trgm      on public.products using gin (name      extensions.gin_trgm_ops);
create index products_name_ar_trgm   on public.products using gin (name_ar   extensions.gin_trgm_ops);
create index products_item_code_trgm on public.products using gin (item_code extensions.gin_trgm_ops);

-- Kit bill of materials: selling 1 kit deducts `qty` of each component.
create table public.kit_components (
  kit_id       uuid not null references public.products (id),
  component_id uuid not null references public.products (id),
  qty          integer not null check (qty > 0),
  primary key (kit_id, component_id),
  check (kit_id <> component_id)
);

-- One level of nesting only (a component cannot itself be a kit).
create or replace function public.guard_kit_components()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if exists (select 1 from public.kit_components where kit_id = new.component_id) then
    raise exception 'nested_kit: component % is itself a kit', new.component_id;
  end if;
  if exists (select 1 from public.kit_components where component_id = new.kit_id) then
    raise exception 'nested_kit: kit % is already a component of another kit', new.kit_id;
  end if;
  return new;
end;
$$;

create trigger kit_components_guard
  before insert or update on public.kit_components
  for each row execute function public.guard_kit_components();

-- ---------------------------------------------------------------------
-- Customers
-- ---------------------------------------------------------------------
create table public.customers (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (btrim(name) <> ''),
  phone       text,
  is_wireless boolean not null default false,
  created_at  timestamptz not null default now()
);
create index customers_name_trgm on public.customers using gin (name extensions.gin_trgm_ops);

-- ---------------------------------------------------------------------
-- Sales
-- SPEC FIX: receipt numbers come from a counter row, not a SEQUENCE.
-- Sequences skip values when a transaction rolls back (e.g. a sale blocked
-- for low stock), which would leave gaps in a numbered receipt book. The
-- counter is updated inside the sale transaction, so a failed sale burns no
-- number. Cost: sales serialise on one row, which is fine for a few staff.
-- ---------------------------------------------------------------------
create table public.receipt_counter (
  singleton   boolean primary key default true check (singleton),
  last_number bigint not null
);
insert into public.receipt_counter (last_number) values (1000);   -- first receipt: R-1001

create table public.sales (
  id             uuid primary key default gen_random_uuid(),
  receipt_number text not null unique,
  client_ref     uuid unique,                 -- idempotency key for the offline queue
  customer_id    uuid references public.customers (id),
  customer_name  text,
  currency       text not null check (currency in ('USD', 'SYP')),
  price_tier     text not null check (price_tier in ('general', 'wireless')),
  total          numeric(14, 2) not null check (total >= 0),
  sold_from      text not null references public.locations (id),
  status         text not null default 'completed' check (status in ('completed', 'cancelled')),
  cancelled_at   timestamptz,
  cancelled_by   uuid references auth.users (id),
  cancel_reason  text,
  user_id        uuid references auth.users (id) default auth.uid(),
  created_at     timestamptz not null default now()
);
create index sales_created_at_idx on public.sales (created_at desc);
create index sales_user_idx on public.sales (user_id, created_at desc);

-- SPEC FIX: no ON DELETE CASCADE — sales are never deleted (rule 5), they
-- are cancelled. Added line_total so reports do not recompute it.
create table public.sale_items (
  id             bigint generated always as identity primary key,
  sale_id        uuid not null references public.sales (id),
  product_id     uuid not null references public.products (id),
  qty            integer not null check (qty > 0),
  unit_price     numeric(14, 2) not null check (unit_price >= 0),
  price_currency text not null check (price_currency in ('USD', 'SYP')),
  line_total     numeric(14, 2) generated always as (qty * unit_price) stored
);
create index sale_items_sale_idx on public.sale_items (sale_id);
create index sale_items_product_idx on public.sale_items (product_id);

-- ---------------------------------------------------------------------
-- Stock movements — the only way stock changes.
-- SPEC FIX: the original schema could only ADD stock on an adjustment, so a
-- stock take that finds fewer units than expected was impossible. An
-- adjustment now has exactly one of to_location (increase) / from_location
-- (decrease). The CHECK below pins the shape of every movement type.
-- ---------------------------------------------------------------------
create table public.stock_movements (
  id            bigint generated always as identity primary key,
  product_id    uuid not null references public.products (id),
  type          text not null check (type in ('receiving', 'sale', 'transfer', 'adjustment', 'return')),
  qty           integer not null check (qty > 0),
  from_location text references public.locations (id),
  to_location   text references public.locations (id),
  sale_id       uuid references public.sales (id),
  user_id       uuid references auth.users (id) default auth.uid(),
  note          text,
  created_at    timestamptz not null default now(),
  constraint movement_shape check (
       (type = 'receiving'  and to_location is not null and from_location is null)
    or (type = 'sale'       and from_location is not null and to_location is null)
    or (type = 'transfer'   and from_location is not null and to_location is not null
                            and from_location <> to_location)
    or (type = 'adjustment' and (from_location is null) <> (to_location is null))
    or (type = 'return'     and to_location is not null and from_location is null)
  )
);
create index stock_movements_product_idx on public.stock_movements (product_id, created_at desc);
create index stock_movements_created_idx on public.stock_movements (created_at desc);
create index stock_movements_sale_idx    on public.stock_movements (sale_id) where sale_id is not null;

-- Append-only: history can never be edited or erased.
create or replace function public.block_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception 'append_only: % on % is not allowed', tg_op, tg_table_name
    using errcode = '42501';
end;
$$;

create trigger stock_movements_append_only
  before update or delete on public.stock_movements
  for each row execute function public.block_mutation();
create trigger stock_movements_no_truncate
  before truncate on public.stock_movements
  for each statement execute function public.block_mutation();
create trigger sales_no_delete
  before delete on public.sales
  for each row execute function public.block_mutation();
create trigger sale_items_append_only
  before update or delete on public.sale_items
  for each row execute function public.block_mutation();

-- ---------------------------------------------------------------------
-- Derived stock (never stored)
-- Every movement adds to to_location and subtracts from from_location.
-- SPEC FIX: rewritten from the spec's cross join over stock_movements. This
-- lists every product × location (zeros included, which the stock matrix
-- needs) and uses the from/to rule above, which also makes decreasing
-- adjustments work.
-- The view runs with its owner's rights (so sales staff can read stock
-- without read access to the movements log) and gates itself by role.
-- ---------------------------------------------------------------------
create or replace function public.stock_of(p_product uuid, p_location text)
returns integer
language sql stable
set search_path = public
as $$
  select (
    coalesce(sum(qty) filter (where to_location = p_location), 0)
  - coalesce(sum(qty) filter (where from_location = p_location), 0)
  )::integer
  from public.stock_movements
  where product_id = p_product
    and (to_location = p_location or from_location = p_location)
$$;

create view public.stock_view as
with deltas as (
  select product_id, to_location as location, sum(qty) as qty
  from public.stock_movements where to_location is not null
  group by product_id, to_location
  union all
  select product_id, from_location, -sum(qty)
  from public.stock_movements where from_location is not null
  group by product_id, from_location
)
select p.id as product_id,
       l.id as location,
       coalesce(sum(d.qty), 0)::integer as qty
from public.products p
cross join public.locations l
left join deltas d on d.product_id = p.id and d.location = l.id
where (select public.app_role()) is not null
group by p.id, l.id;

create view public.stock_totals as
select product_id, sum(qty)::integer as total_qty
from public.stock_view
group by product_id;

-- ===================== 0002_functions.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0002: business-logic RPCs
--
-- Every stock change goes through one of these functions. They run with
-- owner rights (security definer), check the caller's role themselves, take
-- a per-(product, location) lock so two phones cannot both sell the last
-- unit, and write the movement rows. Clients have NO direct INSERT on
-- stock_movements / sales / sale_items (see 0003).
--
-- Errors carry a machine-readable prefix before the colon, e.g.
-- 'insufficient_stock: ...', so the UI can map them to translated messages.
-- =====================================================================

-- Rows a sale needs from stock: each line itself, plus (for kits) every
-- component × its BOM quantity. Internal helper.
create or replace function public.sale_requirements(p_sale_id uuid)
returns table (product_id uuid, qty integer)
language sql stable
set search_path = public
as $$
  select t.product_id, sum(t.qty)::integer
  from (
    select si.product_id, si.qty
    from public.sale_items si
    where si.sale_id = p_sale_id
    union all
    select kc.component_id, si.qty * kc.qty
    from public.sale_items si
    join public.kit_components kc on kc.kit_id = si.product_id
    where si.sale_id = p_sale_id
  ) t
  group by t.product_id
$$;

-- ---------------------------------------------------------------------
-- receive_stock: a delivery arrives
-- ---------------------------------------------------------------------
create or replace function public.receive_stock(
  p_product  uuid,
  p_location text,
  p_qty      integer,
  p_note     text default null
) returns bigint
language plpgsql security definer
set search_path = public
as $$
declare
  v_id bigint;
begin
  perform public.require_role('admin', 'warehouse');

  if p_qty is null or p_qty <= 0 then
    raise exception 'invalid_qty: qty must be a positive integer';
  end if;
  if not exists (select 1 from public.products where id = p_product and active) then
    raise exception 'unknown_product: %', p_product;
  end if;
  if not exists (select 1 from public.locations where id = p_location) then
    raise exception 'unknown_location: %', p_location;
  end if;

  insert into public.stock_movements (product_id, type, qty, to_location, user_id, note)
  values (p_product, 'receiving', p_qty, p_location, auth.uid(), p_note)
  returning id into v_id;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------
-- transfer_stock: move units between locations (validates availability)
-- ---------------------------------------------------------------------
create or replace function public.transfer_stock(
  p_product uuid,
  p_from    text,
  p_to      text,
  p_qty     integer,
  p_note    text default null
) returns bigint
language plpgsql security definer
set search_path = public
as $$
declare
  v_id        bigint;
  v_available integer;
begin
  perform public.require_role('admin', 'warehouse');

  if p_qty is null or p_qty <= 0 then
    raise exception 'invalid_qty: qty must be a positive integer';
  end if;
  if p_from is null or p_to is null or p_from = p_to then
    raise exception 'invalid_transfer: source and destination must be two different locations';
  end if;
  if not exists (select 1 from public.products where id = p_product and active) then
    raise exception 'unknown_product: %', p_product;
  end if;
  if not exists (select 1 from public.locations where id = p_from)
     or not exists (select 1 from public.locations where id = p_to) then
    raise exception 'unknown_location';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_product::text || ':' || p_from, 0));

  v_available := public.stock_of(p_product, p_from);
  if v_available < p_qty then
    raise exception 'insufficient_stock: only % in % but % requested', v_available, p_from, p_qty;
  end if;

  insert into public.stock_movements (product_id, type, qty, from_location, to_location, user_id, note)
  values (p_product, 'transfer', p_qty, p_from, p_to, auth.uid(), p_note)
  returning id into v_id;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------
-- stock_take: staff enter the COUNTED quantity; the function writes the
-- adjustment (up or down) that makes the books match. No change → no row.
-- ---------------------------------------------------------------------
create or replace function public.stock_take(
  p_product uuid,
  p_location text,
  p_counted  integer,
  p_note     text default null
) returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_current integer;
  v_delta   integer;
  v_id      bigint;
begin
  perform public.require_role('admin', 'warehouse');

  if p_counted is null or p_counted < 0 then
    raise exception 'invalid_qty: counted quantity must be zero or more';
  end if;
  if not exists (select 1 from public.products where id = p_product and active) then
    raise exception 'unknown_product: %', p_product;
  end if;
  if not exists (select 1 from public.locations where id = p_location) then
    raise exception 'unknown_location: %', p_location;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_product::text || ':' || p_location, 0));

  v_current := public.stock_of(p_product, p_location);
  v_delta   := p_counted - v_current;

  if v_delta > 0 then
    insert into public.stock_movements (product_id, type, qty, to_location, user_id, note)
    values (p_product, 'adjustment', v_delta, p_location, auth.uid(),
            coalesce(p_note, 'stock take: counted ' || p_counted || ', books ' || v_current))
    returning id into v_id;
  elsif v_delta < 0 then
    insert into public.stock_movements (product_id, type, qty, from_location, user_id, note)
    values (p_product, 'adjustment', -v_delta, p_location, auth.uid(),
            coalesce(p_note, 'stock take: counted ' || p_counted || ', books ' || v_current))
    returning id into v_id;
  end if;

  return jsonb_build_object(
    'movement_id', v_id,
    'previous',    v_current,
    'counted',     p_counted,
    'delta',       v_delta
  );
end;
$$;

-- ---------------------------------------------------------------------
-- complete_sale
--   p_items: [{"product_id": "<uuid>", "qty": 2}, ...]
-- Prices are read from the catalog on the server (the client cannot set a
-- price) and frozen into sale_items (rule 4). Wireless tier uses the wireless
-- price and falls back to the general price when a product has none.
-- p_client_ref makes retries from the offline queue idempotent.
-- Returns {sale_id, receipt_number, total, currency, created_at, duplicate}.
-- ---------------------------------------------------------------------
create or replace function public.complete_sale(
  p_currency      text,
  p_price_tier    text,
  p_sold_from     text,
  p_items         jsonb,
  p_customer_id   uuid default null,
  p_customer_name text default null,
  p_client_ref    uuid default null
) returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_sale_id  uuid := gen_random_uuid();
  v_number   bigint;
  v_receipt  text;
  v_total    numeric(14, 2);
  v_created  timestamptz;
  v_cname    text;
  v_line     record;
  v_req      record;
  v_prod     public.products%rowtype;
  v_price    numeric;
  v_short    jsonb;
  v_existing public.sales%rowtype;
begin
  perform public.require_role('admin', 'sales');

  if p_currency is null or p_currency not in ('USD', 'SYP') then
    raise exception 'invalid_currency: %', p_currency;
  end if;
  if p_price_tier is null or p_price_tier not in ('general', 'wireless') then
    raise exception 'invalid_tier: %', p_price_tier;
  end if;
  if not exists (select 1 from public.locations where id = p_sold_from) then
    raise exception 'unknown_location: %', p_sold_from;
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'empty_cart: at least one item is required';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_items) as x(product_id uuid, qty integer)
    where x.product_id is null or x.qty is null or x.qty <= 0
  ) then
    raise exception 'invalid_item: every item needs a product_id and a positive integer qty';
  end if;

  -- Retry of a sale that already went through: return it, change nothing.
  if p_client_ref is not null then
    perform pg_advisory_xact_lock(hashtextextended('sale:' || p_client_ref::text, 0));
    select * into v_existing from public.sales where client_ref = p_client_ref;
    if found then
      return jsonb_build_object(
        'sale_id', v_existing.id, 'receipt_number', v_existing.receipt_number,
        'total', v_existing.total, 'currency', v_existing.currency,
        'created_at', v_existing.created_at, 'duplicate', true);
    end if;
  end if;

  if p_customer_id is not null then
    select name into v_cname from public.customers where id = p_customer_id;
    if not found then
      raise exception 'unknown_customer: %', p_customer_id;
    end if;
  else
    v_cname := nullif(btrim(p_customer_name), '');
  end if;

  -- Gap-free receipt number (rolls back with the sale if anything below fails).
  update public.receipt_counter set last_number = last_number + 1
  returning last_number into v_number;
  v_receipt := 'R-' || v_number;

  insert into public.sales
    (id, receipt_number, client_ref, customer_id, customer_name,
     currency, price_tier, total, sold_from, user_id)
  values
    (v_sale_id, v_receipt, p_client_ref, p_customer_id, v_cname,
     p_currency, p_price_tier, 0, p_sold_from, auth.uid())
  returning created_at into v_created;

  -- Lines (duplicate product lines are merged), priced from the catalog.
  for v_line in
    select x.product_id, sum(x.qty)::integer as qty
    from jsonb_to_recordset(p_items) as x(product_id uuid, qty integer)
    group by x.product_id
    order by x.product_id
  loop
    select * into v_prod from public.products where id = v_line.product_id;
    if not found or not v_prod.active or not v_prod.for_sale then
      raise exception 'not_for_sale: product % is not available for sale', v_line.product_id;
    end if;

    v_price := case
      when p_currency = 'USD' and p_price_tier = 'wireless' then coalesce(v_prod.wireless_price_usd, v_prod.price_usd)
      when p_currency = 'USD'                                then v_prod.price_usd
      when p_price_tier = 'wireless'                         then coalesce(v_prod.wireless_price_syp, v_prod.price_syp)
      else v_prod.price_syp
    end;
    if v_price is null or v_price <= 0 then
      raise exception 'no_price: % has no % price in %', v_prod.item_code, p_price_tier, p_currency;
    end if;

    insert into public.sale_items (sale_id, product_id, qty, unit_price, price_currency)
    values (v_sale_id, v_line.product_id, v_line.qty, v_price, p_currency);
  end loop;

  -- Lock every (product, location) pair in a fixed order, then check ALL of
  -- them so the cashier sees every shortage at once.
  for v_req in
    select r.product_id from public.sale_requirements(v_sale_id) r order by r.product_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_req.product_id::text || ':' || p_sold_from, 0));
  end loop;

  select jsonb_agg(
           jsonb_build_object(
             'product_id', r.product_id,
             'item_code',  p.item_code,
             'needed',     r.qty,
             'available',  public.stock_of(r.product_id, p_sold_from))
           order by p.item_code)
  into v_short
  from public.sale_requirements(v_sale_id) r
  join public.products p on p.id = r.product_id
  where public.stock_of(r.product_id, p_sold_from) < r.qty;

  if v_short is not null then
    raise exception 'insufficient_stock: not enough stock in %', p_sold_from
      using detail = v_short::text;
  end if;

  insert into public.stock_movements (product_id, type, qty, from_location, sale_id, user_id, note)
  select r.product_id, 'sale', r.qty, p_sold_from, v_sale_id, auth.uid(), v_receipt
  from public.sale_requirements(v_sale_id) r;

  select sum(line_total) into v_total from public.sale_items where sale_id = v_sale_id;
  update public.sales set total = v_total where id = v_sale_id;

  return jsonb_build_object(
    'sale_id', v_sale_id, 'receipt_number', v_receipt, 'total', v_total,
    'currency', p_currency, 'created_at', v_created, 'duplicate', false);
end;
$$;

-- ---------------------------------------------------------------------
-- cancel_sale: soft-cancel (admin). Receipt number stays used; the units go
-- back to the location they left via 'return' movements.
-- ---------------------------------------------------------------------
create or replace function public.cancel_sale(
  p_sale_id uuid,
  p_reason  text default null
) returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_sale public.sales%rowtype;
begin
  perform public.require_role('admin');

  select * into v_sale from public.sales where id = p_sale_id for update;
  if not found then
    raise exception 'unknown_sale: %', p_sale_id;
  end if;
  if v_sale.status <> 'completed' then
    raise exception 'already_cancelled: receipt % is already cancelled', v_sale.receipt_number;
  end if;

  insert into public.stock_movements (product_id, type, qty, to_location, sale_id, user_id, note)
  select m.product_id, 'return', m.qty, m.from_location, m.sale_id, auth.uid(),
         'cancelled ' || v_sale.receipt_number
  from public.stock_movements m
  where m.sale_id = p_sale_id and m.type = 'sale';

  update public.sales
     set status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = p_reason
   where id = p_sale_id;

  return jsonb_build_object('sale_id', p_sale_id, 'receipt_number', v_sale.receipt_number, 'status', 'cancelled');
end;
$$;

-- ===================== 0003_rls.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0003: privileges and row-level security
--
-- Two layers, both enforced by Postgres (not by hiding buttons):
--   1. GRANTs: authenticated users get only the table operations they could
--      ever need; anon gets nothing.
--   2. RLS policies: which ROWS each role may touch.
-- Writes to stock/sales go exclusively through the RPCs in 0002.
--
--   admin      everything
--   sales      products (read), customers, stock (read), own sales
--   warehouse  products (read), stock + movements
-- =====================================================================

-- Start from zero: Supabase grants new public tables to anon/authenticated.
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f'
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

-- Table privileges ----------------------------------------------------
grant select                          on public.locations      to authenticated;
grant select, insert, update, delete  on public.staff_roles    to authenticated;  -- rows limited to admin by RLS
grant select, insert, update          on public.products       to authenticated;  -- no DELETE: soft delete = active=false
grant select, insert, update, delete  on public.kit_components to authenticated;
grant select, insert, update          on public.customers      to authenticated;
grant select                          on public.sales          to authenticated;
grant select                          on public.sale_items     to authenticated;
grant select                          on public.stock_movements to authenticated;
grant select                          on public.stock_view     to authenticated;
grant select                          on public.stock_totals   to authenticated;
-- receipt_counter: no grants at all (only complete_sale touches it)

-- Function privileges -------------------------------------------------
grant execute on function public.app_role()                                        to authenticated;
grant execute on function public.receive_stock(uuid, text, integer, text)          to authenticated;
grant execute on function public.transfer_stock(uuid, text, text, integer, text)   to authenticated;
grant execute on function public.stock_take(uuid, text, integer, text)             to authenticated;
grant execute on function public.complete_sale(text, text, text, jsonb, uuid, text, uuid) to authenticated;
grant execute on function public.cancel_sale(uuid, text)                           to authenticated;

-- Enable RLS ----------------------------------------------------------
alter table public.locations       enable row level security;
alter table public.staff_roles     enable row level security;
alter table public.products        enable row level security;
alter table public.kit_components  enable row level security;
alter table public.customers       enable row level security;
alter table public.receipt_counter enable row level security;   -- no policies = closed
alter table public.sales           enable row level security;
alter table public.sale_items      enable row level security;
alter table public.stock_movements enable row level security;

-- locations -----------------------------------------------------------
create policy locations_read on public.locations
  for select to authenticated
  using ((select public.app_role()) is not null);

-- staff_roles: everyone sees their own row (the app needs it to pick the
-- menu); admins see and manage all.
create policy staff_roles_read on public.staff_roles
  for select to authenticated
  using (user_id = (select auth.uid()) or (select public.app_role()) = 'admin');
create policy staff_roles_admin_write on public.staff_roles
  for all to authenticated
  using ((select public.app_role()) = 'admin')
  with check ((select public.app_role()) = 'admin');

-- products ------------------------------------------------------------
create policy products_read on public.products
  for select to authenticated
  using ((select public.app_role()) is not null);
create policy products_admin_insert on public.products
  for insert to authenticated
  with check ((select public.app_role()) = 'admin');
create policy products_admin_update on public.products
  for update to authenticated
  using ((select public.app_role()) = 'admin')
  with check ((select public.app_role()) = 'admin');

-- kit_components ------------------------------------------------------
create policy kit_components_read on public.kit_components
  for select to authenticated
  using ((select public.app_role()) is not null);
create policy kit_components_admin_write on public.kit_components
  for all to authenticated
  using ((select public.app_role()) = 'admin')
  with check ((select public.app_role()) = 'admin');

-- customers -----------------------------------------------------------
create policy customers_read on public.customers
  for select to authenticated
  using ((select public.app_role()) in ('admin', 'sales'));
create policy customers_insert on public.customers
  for insert to authenticated
  with check ((select public.app_role()) in ('admin', 'sales'));
create policy customers_update on public.customers
  for update to authenticated
  using ((select public.app_role()) in ('admin', 'sales'))
  with check ((select public.app_role()) in ('admin', 'sales'));

-- sales / sale_items: admin sees all, sales sees only their own ------
create policy sales_read on public.sales
  for select to authenticated
  using (
    (select public.app_role()) = 'admin'
    or ((select public.app_role()) = 'sales' and user_id = (select auth.uid()))
  );

create policy sale_items_read on public.sale_items
  for select to authenticated
  using (exists (select 1 from public.sales s where s.id = sale_items.sale_id));  -- inherits sales RLS

-- stock_movements: the full log is for admin + warehouse -------------
create policy stock_movements_read on public.stock_movements
  for select to authenticated
  using ((select public.app_role()) in ('admin', 'warehouse'));

-- No INSERT/UPDATE/DELETE policies or grants on sales, sale_items or
-- stock_movements: only the SECURITY DEFINER functions can write them.

-- ===================== 0004_import_products.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0004: catalog import
--
-- import_products(rows) merges a parsed CSV into the catalog in ONE
-- transaction (any bad row rolls the whole import back — nothing is half
-- saved). Match key: item_code.
--
-- Merge rule: a key that is ABSENT from a row's JSON is left untouched on
-- an existing product; a key that is PRESENT (even null) is written. So a
-- price-list import can refresh prices without wiping for_sale, barcode,
-- name_ar, etc. New products get column defaults for absent keys.
--
-- Row keys: item_code (required), name (required for new products),
--   name_ar, category, unit, specs, price_usd, price_syp,
--   wireless_price_usd, wireless_price_syp, for_sale, barcode
-- Returns {inserted, updated}.
-- =====================================================================

create or replace function public.import_products(p_rows jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  r       jsonb;
  v_code  text;
  v_id    uuid;
  v_ins   integer := 0;
  v_upd   integer := 0;
  v_seen  text[]  := '{}';
begin
  perform public.require_role('admin');

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid_rows: expected a JSON array';
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    v_code := btrim(r ->> 'item_code');
    if v_code is null or v_code = '' then
      raise exception 'invalid_row: a row has no item_code';
    end if;
    if v_code = any (v_seen) then
      raise exception 'duplicate_code: % appears twice in the import', v_code;
    end if;
    v_seen := v_seen || v_code;

    select id into v_id from public.products where item_code = v_code;

    if v_id is null then
      if nullif(btrim(r ->> 'name'), '') is null then
        raise exception 'invalid_row: new product % has no name', v_code;
      end if;
      insert into public.products
        (item_code, name, name_ar, category, unit, specs,
         price_usd, price_syp, wireless_price_usd, wireless_price_syp, for_sale, barcode)
      values (
        v_code,
        btrim(r ->> 'name'),
        nullif(btrim(r ->> 'name_ar'), ''),
        nullif(btrim(r ->> 'category'), ''),
        coalesce(nullif(btrim(r ->> 'unit'), ''), 'قطعة'),
        nullif(btrim(r ->> 'specs'), ''),
        coalesce((r ->> 'price_usd')::numeric, 0),
        coalesce((r ->> 'price_syp')::numeric, 0),
        (r ->> 'wireless_price_usd')::numeric,
        (r ->> 'wireless_price_syp')::numeric,
        coalesce((r ->> 'for_sale')::boolean, false),
        nullif(btrim(r ->> 'barcode'), '')
      );
      v_ins := v_ins + 1;
    else
      update public.products set
        name      = case when r ? 'name'     and nullif(btrim(r ->> 'name'), '') is not null then btrim(r ->> 'name') else name end,
        name_ar   = case when r ? 'name_ar'  then nullif(btrim(r ->> 'name_ar'), '')  else name_ar  end,
        category  = case when r ? 'category' then nullif(btrim(r ->> 'category'), '') else category end,
        unit      = case when r ? 'unit'     and nullif(btrim(r ->> 'unit'), '') is not null then btrim(r ->> 'unit') else unit end,
        specs     = case when r ? 'specs'    then nullif(btrim(r ->> 'specs'), '')    else specs    end,
        price_usd = case when r ? 'price_usd' then coalesce((r ->> 'price_usd')::numeric, price_usd) else price_usd end,
        price_syp = case when r ? 'price_syp' then coalesce((r ->> 'price_syp')::numeric, price_syp) else price_syp end,
        wireless_price_usd = case when r ? 'wireless_price_usd' then (r ->> 'wireless_price_usd')::numeric else wireless_price_usd end,
        wireless_price_syp = case when r ? 'wireless_price_syp' then (r ->> 'wireless_price_syp')::numeric else wireless_price_syp end,
        for_sale  = case when r ? 'for_sale' then coalesce((r ->> 'for_sale')::boolean, for_sale) else for_sale end,
        barcode   = case when r ? 'barcode'  then nullif(btrim(r ->> 'barcode'), '')  else barcode  end
      where id = v_id;
      v_upd := v_upd + 1;
    end if;
  end loop;

  return jsonb_build_object('inserted', v_ins, 'updated', v_upd);
end;
$$;

-- New functions are executable by PUBLIC/anon by default: lock down, then grant.
revoke all on function public.import_products(jsonb) from public, anon, authenticated;
grant execute on function public.import_products(jsonb) to authenticated;

-- ===================== 0005_claim_first_admin.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0005: first-admin bootstrap
--
-- A brand-new project has no admin, and nobody can grant roles before one
-- exists. claim_first_admin() lets the first signed-in user become admin,
-- and ONLY while no active admin exists. After that it always refuses.
--
-- Safety note: this is first-come-first-served. Create your own account
-- first, claim immediately, and keep public sign-ups switched off in
-- Supabase (Authentication → Providers → Email → "Allow new users to sign up" off).
-- =====================================================================

create or replace function public.claim_first_admin(p_full_name text default null)
returns boolean
language plpgsql security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'forbidden: sign in first' using errcode = '42501';
  end if;

  -- One claim at a time, so two people cannot both win.
  perform pg_advisory_xact_lock(hashtextextended('claim_first_admin', 0));

  if exists (select 1 from public.staff_roles where role = 'admin' and active) then
    return false;
  end if;

  insert into public.staff_roles (user_id, role, full_name, active)
  values (auth.uid(), 'admin', nullif(btrim(p_full_name), ''), true)
  on conflict (user_id) do update
    set role = 'admin', active = true,
        full_name = coalesce(excluded.full_name, public.staff_roles.full_name);
  return true;
end;
$$;

-- True while the project still needs its first admin (used to decide whether
-- to show the "claim ownership" button). Reveals nothing else.
create or replace function public.needs_first_admin()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select not exists (select 1 from public.staff_roles where role = 'admin' and active)
$$;

revoke all on function public.claim_first_admin(text) from public, anon, authenticated;
revoke all on function public.needs_first_admin()     from public, anon, authenticated;
grant execute on function public.claim_first_admin(text) to authenticated;
grant execute on function public.needs_first_admin()     to authenticated;

-- ===================== 0006_system_controls.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0006: exchange rate and clean reset
-- =====================================================================

create table public.app_settings (
  key text primary key,
  numeric_value numeric(18, 4) not null check (numeric_value > 0),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id)
);

insert into public.app_settings (key, numeric_value)
values ('usd_to_syp_rate', 1)
on conflict (key) do nothing;

alter table public.app_settings enable row level security;
grant select on public.app_settings to authenticated;

create policy app_settings_read on public.app_settings
  for select to authenticated
  using ((select public.app_role()) is not null);

create or replace function public.set_usd_to_syp_rate(p_rate numeric)
returns numeric
language plpgsql security definer
set search_path = public
as $$
begin
  perform public.require_role('admin');
  if p_rate is null or p_rate <= 0 then
    raise exception 'invalid_rate: exchange rate must be greater than zero';
  end if;

  update public.app_settings
  set numeric_value = p_rate, updated_at = now(), updated_by = auth.uid()
  where key = 'usd_to_syp_rate';

  update public.products
  set price_syp = round(price_usd * p_rate),
      wireless_price_syp = case
        when wireless_price_usd is null then null
        else round(wireless_price_usd * p_rate)
      end;

  return p_rate;
end;
$$;

create or replace function public.clear_catalog_and_history()
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  perform public.require_role('admin');
  select count(*) into v_count from public.products;

  truncate table
    public.stock_movements,
    public.sale_items,
    public.sales,
    public.customers,
    public.kit_components,
    public.products
    restart identity cascade;

  update public.receipt_counter set last_number = 1000;
  return v_count;
end;
$$;

revoke all on function public.set_usd_to_syp_rate(numeric) from public, anon, authenticated;
grant execute on function public.set_usd_to_syp_rate(numeric) to authenticated;
revoke all on function public.clear_catalog_and_history() from public, anon, authenticated;
grant execute on function public.clear_catalog_and_history() to authenticated;

-- ===================== 0007_display_storage_stock_take.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0007: limit stock takes to visible locations
-- =====================================================================

create or replace function public.stock_take(
  p_product uuid,
  p_location text,
  p_counted  integer,
  p_note     text default null
) returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_current integer;
  v_delta   integer;
  v_id      bigint;
begin
  perform public.require_role('admin', 'warehouse');

  if p_location not in ('display', 'storage') then
    raise exception 'invalid_location: stock takes are limited to display and storage';
  end if;
  if p_counted is null or p_counted < 0 then
    raise exception 'invalid_qty: counted quantity must be zero or more';
  end if;
  if not exists (select 1 from public.products where id = p_product and active) then
    raise exception 'unknown_product: %', p_product;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_product::text || ':' || p_location, 0));

  v_current := public.stock_of(p_product, p_location);
  v_delta   := p_counted - v_current;

  if v_delta > 0 then
    insert into public.stock_movements (product_id, type, qty, to_location, user_id, note)
    values (p_product, 'adjustment', v_delta, p_location, auth.uid(),
            coalesce(p_note, 'stock take: counted ' || p_counted || ', books ' || v_current))
    returning id into v_id;
  elsif v_delta < 0 then
    insert into public.stock_movements (product_id, type, qty, from_location, user_id, note)
    values (p_product, 'adjustment', -v_delta, p_location, auth.uid(),
            coalesce(p_note, 'stock take: counted ' || p_counted || ', books ' || v_current))
    returning id into v_id;
  end if;

  return jsonb_build_object(
    'movement_id', v_id,
    'previous', v_current,
    'counted', p_counted,
    'delta', v_delta
  );
end;
$$;

revoke all on function public.stock_take(uuid, text, integer, text) from public, anon, authenticated;
grant execute on function public.stock_take(uuid, text, integer, text) to authenticated;

-- ===================== 0008_fix_exchange_rate.sql =====================
-- =====================================================================
-- SAM Inventory — migration 0008: exchange-rate update compatibility
-- =====================================================================

create or replace function public.set_usd_to_syp_rate(p_rate numeric)
returns numeric
language plpgsql security definer
set search_path = public
as $$
begin
  perform public.require_role('admin');
  if p_rate is null or p_rate <= 0 then
    raise exception 'invalid_rate: exchange rate must be greater than zero';
  end if;

  update public.app_settings
  set numeric_value = p_rate, updated_at = now(), updated_by = auth.uid()
  where key = 'usd_to_syp_rate';

  update public.products
  set price_syp = round(price_usd * p_rate),
      wireless_price_syp = case
        when wireless_price_usd is null then null
        else round(wireless_price_usd * p_rate)
      end
  where true;

  return p_rate;
end;
$$;

revoke all on function public.set_usd_to_syp_rate(numeric) from public, anon, authenticated;
grant execute on function public.set_usd_to_syp_rate(numeric) to authenticated;

